WITH lines AS (SELECT id, effective_from, currency, EXPLODE(tier_limits) AS element FROM price_tiers) SELECT DATE_TRUNC('WEEK', effective_from) AS week_start, CASE WHEN element >= 87 THEN 'LARGE' ELSE 'SMALL' END AS element_tier, COUNT(*) FILTER (WHERE currency = 'USD') AS usd_rows, COUNT(DISTINCT id) AS distinct_ids FROM lines GROUP BY DATE_TRUNC('WEEK', effective_from), CASE WHEN element >= 87 THEN 'LARGE' ELSE 'SMALL' END ORDER BY usd_rows DESC;
